package owl.nh;
import com.google.gson.*;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.awt.Canvas;
import net.runelite.api.*;
import net.runelite.api.coords.*;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;

/** Real code paths with synthetic observations only. No game startup or inputs. */
public final class OlmLearningTests {
 static void check(boolean ok,String name){CoreTests.check(ok,"Olm learning: "+name);}
 static OlmStrategy.View view(){OlmStrategy.View s=new OlmStrategy.View();s.inRaid=s.alive=s.focused=s.entered=s.magicAlive=s.meleeAlive=s.headAlive=true;s.hpPercent=s.prayerPercent=s.magicHp=s.meleeHp=100;s.phase=OlmStrategy.Phase.REGULAR;return s;}
 public static void main(String[] args)throws Exception{
  Gson gson=new Gson();OlmTargetNetwork n=new OlmTargetNetwork();OlmRunLearning run=new OlmRunLearning();run.start();run.attach(n);OlmStrategy.View s=view();
  String before=gson.toJson(n.checkpoint());run.requested(s,"magic",10);run.observe(10,100,100,100,100);check(n.checkpoint().onlineUpdates==0,"same-tick state is not an outcome");run.observe(11,90,80,100,100);check(n.checkpoint().onlineUpdates==1&&!before.equals(gson.toJson(n.checkpoint())),"actual next-state outcome updates neural weights automatically");
  run.requested(s,"melee",12);run.observe(16,90,80,-1,100);check(n.checkpoint().onlineUpdates==1,"unknown target health is not rewarded");
  run.finish(false);run.finish(true);check((Boolean)run.export().get("lootConfirmed"),"explicit loot confirmation works after Stop");int finishedUpdates=n.checkpoint().onlineUpdates;run.finish(true);check(n.checkpoint().onlineUpdates==finishedUpdates,"repeated confirmation cannot multiply terminal rewards");
  OlmTargetNetwork restored=OlmTargetNetwork.restore(gson.fromJson(gson.toJson(n.checkpoint()),OlmTargetNetwork.Checkpoint.class));check(gson.toJson(restored.checkpoint()).equals(gson.toJson(n.checkpoint())),"neural checkpoint restores weights and counters exactly");
  OlmTargetNetwork.Checkpoint bad=n.checkpoint();bad.w[0][0]=Double.NaN;boolean rejected=false;try{OlmTargetNetwork.restore(bad);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"nonfinite checkpoint rejected");
  run.start();run.attach(n);run.requested(s,"magic",17);run.observe(18,90,80,100,100);int beforeDeath=n.checkpoint().onlineUpdates;run.failed();check(n.checkpoint().onlineUpdates>beforeDeath&&(Boolean)run.export().get("deathObserved"),"observed death supplies limited terminal feedback");int afterDeath=n.checkpoint().onlineUpdates;run.failed();check(n.checkpoint().onlineUpdates==afterDeath,"death feedback applied once");run.start();run.attach(n);for(int i=0;i<1030;i++){run.requested(s,"magic",i*5+20);run.observe(i*5+24,100,100,100,100);}check(run.samples()==1024,"run experience bounded");
  JsonObject profile=new JsonParser().parse(Files.readString(CombatRuntime.projectRoot().toPath().resolve("profiles/olm-demo2-candidate.json"))).getAsJsonObject();profile.addProperty("schema",OlmPresetStore.SCHEMA);profile.add("targetNetwork",gson.toJsonTree(n.checkpoint()));profile.add("movementLearning",new JsonParser().parse(new OlmSpecials().exportLearning()));OlmActionLearning timings=new OlmActionLearning();timings.confirmed("gear",1);profile.add("actionTiming",gson.toJsonTree(timings.checkpoint()));profile.add("runExperience",gson.toJsonTree(run.export()));
  profile.add("attackSpeeds",gson.toJsonTree(new CombatCore.Settings().speeds));Map<String,String> corrections=new HashMap<>();corrections.put("REGULAR:true:true:true:5:5","magic");profile.add("targetCorrections",gson.toJsonTree(corrections));String json=gson.toJson(profile);OlmPresetStore.Loaded loaded=OlmPresetStore.parse(json);check(loaded.network!=null&&loaded.timing.confirmed==1&&loaded.speeds.get("MAGIC")==5&&loaded.corrections.size()==1,"preset validates model, movement, timing and equipment together");
  OlmPrayerLearning prayers=new OlmPrayerLearning();prayers.acknowledged(12);profile.add("prayerTiming",gson.toJsonTree(prayers.checkpoint()));profile.add("offensivePrayers",gson.toJsonTree(OlmOffensivePrayers.defaults()));json=gson.toJson(profile);loaded=OlmPresetStore.parse(json);check(loaded.prayerTiming.marginCycles==14,"learned prayer timing survives preset roundtrip");OlmFighter.Profile settings=gson.fromJson(loaded.json,OlmFighter.Profile.class);check(settings.offensivePrayersEnabled&&settings.offensivePrayers.get("MAGIC").equals("AUGURY"),"offensive prayer settings survive preset roundtrip");
  Path workspace=CombatRuntime.projectRoot().toPath().toAbsolutePath().normalize(),temp=Files.createTempDirectory(workspace.resolve("build"),"olm-learning-checks-");check(temp.toAbsolutePath().normalize().startsWith(workspace),"test cleanup target inside project");
  try{Path first=OlmPresetStore.save(temp,json),second=OlmPresetStore.save(temp,json);check(!first.equals(second)&&Files.readString(first).equals(json),"confirmed outputs get unique names without overwrites");OlmPresetStore.parse(Files.readString(second));JsonObject invalid=profile.deepCopy();invalid.getAsJsonObject("targetNetwork").add("w",new JsonArray());rejected=false;try{OlmPresetStore.parse(invalid.toString());}catch(IllegalArgumentException e){rejected=true;}check(rejected,"malformed model rejected before live state changes");}
  finally{try(java.util.stream.Stream<Path> files=Files.walk(temp)){for(Path p:(Iterable<Path>)files.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}
  OlmMechanicAdapter.Config signals=new OlmMechanicAdapter.Config();Map<Integer,OlmSpecials.Orb> orbs=OlmMechanicAdapter.effectiveOrbs(signals);check(orbs.get(1341)==OlmSpecials.Orb.PURPLE&&orbs.get(1343)==OlmSpecials.Orb.GREEN&&orbs.get(1345)==OlmSpecials.Orb.RED,"published orb styles mapped");check(OlmMechanicAdapter.wallNpc(signals,7558,"<col=00ffff>Fire</col>"),"recorded fire NPC recognized regardless of markup");
  OlmStrategy prep=new OlmStrategy();s=view();s.hpPercent=99;for(String name:Arrays.asList("overload","enhance","aid","aid","aid","aid","revitalisation")){check(prep.choose(s).value.equals(name),"healthy preparation follows the configured dose order");prep.drinkConfirmed();}
  attempts(profile);fastLoop(profile);System.out.println("Olm online learning checks passed: observed-outcome updates, bounded experience, confirmation, checkpoint/preset roundtrip, invalid data, orb/fire mappings, preparation and same-tick safety reaction. No live inputs.");
 }
 static void awaitSave(OlmFighter fighter)throws Exception{long until=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(5);while(fighter.attemptSaving()&&System.nanoTime()<until)Thread.sleep(10);check(!fighter.attemptSaving(),"attempt writer finishes");}
 private static void attempts(JsonObject profile)throws Exception{
  OlmAttemptLifecycle life=new OlmAttemptLifecycle();life.start(5);check(!life.observe(5,true,"a")&&!life.observe(104,true,"a")&&life.observe(105,true,"a"),"stall requires one hundred ticks without observed progress");life.start(5);life.observe(5,true,"a");check(!life.observe(110,false,"a")&&!life.observe(111,true,"a"),"focus loss or stale observation is a pause rather than a stall");check(life.end()&&!life.end(),"attempt termination is idempotent even when input flags were already cleared");
  OlmRunLearning run=new OlmRunLearning();OlmTargetNetwork network=new OlmTargetNetwork();run.start();run.attach(network);run.requested(view(),"magic",1);run.observe(2,100,80,100,100);run.bossDefeated();int updates=network.updateCount();run.finish(true);check(network.updateCount()==updates&&(Boolean)run.export().get("bossDefeated")&&(Boolean)run.export().get("lootConfirmed"),"head death then loot confirmation cannot duplicate success reward");run.start();run.attach(network);run.failed();boolean rejected=false;try{run.finish(true);}catch(IllegalStateException e){rejected=true;}check(rejected,"death cannot later be relabelled as a successful attempt");
  Path temp=Files.createTempDirectory(CombatRuntime.projectRoot().toPath().resolve("build"),"olm-attempt-checks-");
  try{
   JsonObject data=profile.deepCopy();data.addProperty("schema",OlmPresetStore.SCHEMA);data.add("targetNetwork",new Gson().toJsonTree(network.checkpoint()));String id=UUID.randomUUID().toString();JsonObject meta=new JsonObject();meta.addProperty("id",id);meta.addProperty("outcome","RUNNING");data.add("attempt",meta);
   Path first=OlmAttemptStore.save(temp,id,data.toString());String recovered=OlmAttemptStore.recover(temp,OlmAttemptStore.latest(temp));check(new JsonParser().parse(recovered).getAsJsonObject().getAsJsonObject("attempt").get("outcome").getAsString().equals("INTERRUPTED"),"crash recovery marks unfinished checkpoint interrupted");check(OlmPresetStore.parse(recovered).network.updateCount()==network.updateCount(),"resume restores checkpoint without replaying already-learned experiences");
   String second=UUID.randomUUID().toString();meta.addProperty("id",second);meta.addProperty("outcome","DEATH");OlmAttemptStore.save(temp,second,data.toString());check(Files.exists(first)&&OlmAttemptStore.latest(temp).contains(second),"next attempt preserves history and advances automatic resume checkpoint");
   Files.writeString(OlmAttemptStore.directory(temp).resolve("latest.json"),"broken");check(OlmAttemptStore.latest(temp)!=null,"damaged latest pointer recovers from a valid attempt file");
   rejected=false;try{OlmAttemptStore.save(temp,"../bad",data.toString());}catch(IllegalArgumentException e){rejected=true;}check(rejected,"attempt filename cannot escape its local directory");
  }finally{try(java.util.stream.Stream<Path> files=Files.walk(temp)){for(Path p:(Iterable<Path>)files.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}
 }
 private static void fastLoop(JsonObject profile)throws Exception{
  Map<String,Object> actor=new HashMap<>();actor.put("getLocalLocation",new LocalPoint(128,128));actor.put("getWorldLocation",new WorldPoint(3201,3201,0));Player player=ChambersTests.fake(Player.class,actor);
  Map<String,Object> fields=new HashMap<>();fields.put("isClientThread",true);fields.put("getGameState",GameState.LOGGED_IN);fields.put("getLocalPlayer",player);fields.put("getNpcs",Collections.emptyList());fields.put("getPlayers",Collections.emptyList());fields.put("getPlayerOptions",new String[0]);fields.put("getBoostedSkillLevel",99);fields.put("getRealSkillLevel",99);fields.put("getGameCycle",100);fields.put("getTickCount",10);fields.put("getBaseX",3200);fields.put("getBaseY",3200);final boolean[] focused={false};fields.put("getCanvas",new Canvas(){public boolean isFocusOwner(){return focused[0];}});
  Client client=ChambersTests.fake(Client.class,fields);java.lang.reflect.Constructor<ClientThread> ctor=ClientThread.class.getDeclaredConstructor(Client.class);ctor.setAccessible(true);CombatRuntime runtime=new CombatRuntime(client,ctor.newInstance(client),new EventBus(),null);
  Path attemptTemp=Files.createTempDirectory(CombatRuntime.projectRoot().toPath().resolve("build"),"olm-runtime-attempt-");runtime.olm.attemptRoot=attemptTemp;
  try{JsonObject candidate=profile.deepCopy();candidate.addProperty("provisionalTest",false);candidate.addProperty("verifiedForOrion",true);candidate.addProperty("magicAutocastVerified",true);candidate.addProperty("entryObjectId",-1);runtime.olm.loadPreset(candidate.toString());int retainedUpdates=OlmPresetStore.parse(runtime.olm.profileText()).network.updateCount();runtime.olm.startMain();JsonObject mainSetup=new JsonParser().parse(runtime.olm.profileText()).getAsJsonObject();check(mainSetup.get("provisionalTest").getAsBoolean()&&mainSetup.get("entryObjectId").getAsInt()==-1,"main runner accepts an existing strict profile without a captured door and enables live discovery");check(OlmPresetStore.parse(runtime.olm.profileText()).network.updateCount()==retainedUpdates,"startup mode migration preserves learned model weights and counters");runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.contains("focus"),"unfocused synthetic client produces no inputs");focused[0]=true;fields.put("getGameCycle",101);Map<String,Object> incoming=new HashMap<>();incoming.put("getId",1339);incoming.put("getEndCycle",1000);incoming.put("getInteracting",player);runtime.chambers.projectile(ChambersTests.fake(Projectile.class,incoming));runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.startsWith("PRAYER FIRST"),"actual fighter blocks potion preparation when a protection is required even if its UI is unavailable: "+runtime.olm.status);fields.put("getGameCycle",102);fields.put("getBoostedSkillLevel",0);runtime.olm.tick(true);check(runtime.olm.running&&runtime.olm.status.contains("Death"),"death keeps the runner active for pre-room recovery");awaitSave(runtime.olm);JsonObject savedAttempt=new JsonParser().parse(OlmAttemptStore.latest(attemptTemp)).getAsJsonObject();check(savedAttempt.getAsJsonObject("attempt").get("outcome").getAsString().equals("DEATH_RECOVERING")&&savedAttempt.getAsJsonObject("runExperience").get("deathObserved").getAsBoolean(),"actual death path automatically saves even an attempt without attacks");runtime.config.gear.get(CombatCore.Style.MAGIC).remove(Integer.valueOf(21024));runtime.config.gear.get(CombatCore.Style.MAGIC).add(24668);runtime.olm.close();awaitSave(runtime.olm);fields.put("getBoostedSkillLevel",99);runtime.olm.startMain();check(runtime.config.gear.get(CombatCore.Style.MAGIC).contains(24668)&&!runtime.config.gear.get(CombatCore.Style.MAGIC).contains(21024),"newly selected Twisted ancestral bottoms survive automatic checkpoint loading");check(runtime.olm.running,"main runner automatically resumes a previous attempt without demonstration reload");runtime.olm.manualPhase(3);Map<String,Object> headFields=new HashMap<>();headFields.put("getId",7554);runtime.olm.actorDeath(ChambersTests.fake(NPC.class,headFields));awaitSave(runtime.olm);savedAttempt=new JsonParser().parse(OlmAttemptStore.latest(attemptTemp)).getAsJsonObject();check(runtime.olm.running&&runtime.olm.status.contains("reward chest")&&savedAttempt.getAsJsonObject("attempt").get("outcome").getAsString().equals("COMPLETED")&&!savedAttempt.getAsJsonObject("runExperience").get("lootConfirmed").getAsBoolean(),"actual head-death path stays active for chest collection and saves head death without inventing loot");}
  finally{runtime.olm.close();runtime.chambers.close();runtime.agent.close();runtime.nhTraining.close();awaitSave(runtime.olm);try(java.util.stream.Stream<Path> files=Files.walk(attemptTemp)){for(Path p:(Iterable<Path>)files.sorted(Comparator.reverseOrder())::iterator)Files.delete(p);}}
 }
}
